package com.example.campshare.web;
import com.example.campshare.dashboard.DashboardMapper; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class AdminDashboardController { private final DashboardMapper mapper; public AdminDashboardController(DashboardMapper mapper){this.mapper=mapper;} @GetMapping("/admin/dashboard") public String dashboard(Model model){model.addAttribute("summary",mapper.findSummary());return "admin/dashboard";} @GetMapping("/admin/rentals") public String reservations(@RequestParam(defaultValue="") String userName,@RequestParam(defaultValue="") String gearName,Model model){model.addAttribute("userName",userName);model.addAttribute("gearName",gearName);model.addAttribute("reservations",mapper.findReservations(userName.trim(),gearName.trim()));return "admin/rentals";} @GetMapping("/admin/gears/out-of-stock") public String outOfStock(@RequestParam(defaultValue="") String gearName,@RequestParam(defaultValue="") String category,Model model){model.addAttribute("gearName",gearName);model.addAttribute("category",category);model.addAttribute("gears",mapper.findOutOfStockGears(gearName.trim(),category.trim()));return "admin/out-of-stock";} }
